"use client";

import {
  Archive,
  ArrowSquareOut,
  Copy,
  DotsThreeVertical,
  FolderSimple,
  FolderSimplePlus,
  Funnel,
  Info,
  List,
  PencilSimple,
  Plus,
  SortAscending,
  SquaresFour,
  Trash,
  User,
  Users,
} from "@phosphor-icons/react";
import { cn } from "@workspace/ui/lib/utils";
import { useMemo, useState } from "react";
import type { ReactNode } from "react";

import { Avatar, AvatarFallback, AvatarImage } from "../../avatar";
import { Button } from "../../button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "../../dropdown-menu";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../tabs";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "../../tooltip";

export interface Demostack {
  id: string;
  title: string;
  author: string;
  avatar: string;
  image: string;
}

export const demostacks: Demostack[] = [
  {
    id: "1",
    title: "Product Launch Deck",
    author: "Emma Watson",
    avatar: "https://assets.watermelon.sh/wm_emma.png",
    image: "https://assets.watermelon.sh/hero-2.avif",
  },
  {
    id: "2",
    title: "Q3 Sales Performance",
    author: "Alex Rivera",
    avatar: "https://assets.watermelon.sh/wm_alex.png",
    image: "https://assets.watermelon.sh/hero-8-bg.avif",
  },
  {
    id: "3",
    title: "Design System Overview",
    author: "Mia Chen",
    avatar: "https://assets.watermelon.sh/wm_mia.png",
    image: "https://assets.watermelon.sh/hero-22-bg.avif",
  },
];

const demostackAuthors = [...new Set(demostacks.map((demostack: Demostack) => demostack.author))];

const sortLabels = {
  recent: "Recent",
  ascending: "Title A-Z",
  descending: "Title Z-A",
} as const;

type SortMode = keyof typeof sortLabels;
type ViewMode = "grid" | "list";

function getInitials(name: string) {
  return name
    .trim()
    .split(/\\s+/)
    .map((part) => part[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);
}

export function DemostacksContent() {
  const [sort, setSort] = useState<SortMode>("recent");
  const [selectedAuthors, setSelectedAuthors] = useState<string[]>([]);
  const [view, setView] = useState<ViewMode>("grid");

  const visibleDemostacks = useMemo(() => {
    const filtered = selectedAuthors.length
      ? demostacks.filter((demostack) => selectedAuthors.includes(demostack.author))
      : demostacks;

    if (sort === "ascending") {
      return [...filtered].sort((a, b) => a.title.localeCompare(b.title));
    }
    if (sort === "descending") {
      return [...filtered].sort((a, b) => b.title.localeCompare(a.title));
    }
    return filtered;
  }, [selectedAuthors, sort]);

  return (
    <TooltipProvider delay={300}>
      <Tabs defaultValue="demostacks" className="min-w-0">
        <main className="w-full min-w-0 px-4 py-6 sm:p-7">
          <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-semibold">Team Demostacks</h2>
              <Tooltip>
                <TooltipTrigger
                  render={
                    <Button
                      variant="ghost"
                      size="icon-xs"
                      className="rounded-full text-muted-foreground"
                      aria-label="About Team Demostacks"
                    >
                      <Info className="size-4" />
                    </Button>
                  }
                />
                <TooltipContent>Demostacks shared with everyone in your workspace</TooltipContent>
              </Tooltip>
            </div>

            <div className="flex w-full flex-wrap items-center justify-between gap-3 sm:w-auto sm:flex-nowrap sm:justify-start sm:gap-4">
              <TabsList className="h-10! gap-0 rounded-xl shadow-border">
                <PrimaryTab value="demostacks">Demostacks</PrimaryTab>
                <PrimaryTab value="screenshots">Screenshots</PrimaryTab>
              </TabsList>
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button size="lg" className="rounded-xl shadow-primary">
                      Create
                      <Plus className="size-5" />
                    </Button>
                  }
                />
                <DropdownMenuContent align="end" className="w-48">
                  <DropdownMenuItem>
                    <Plus />
                    New Demostack
                  </DropdownMenuItem>
                  <DropdownMenuItem>
                    <Plus />
                    New Screenshot
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>

          <TabsContent value="demostacks">
            <Tabs defaultValue="shared" className="mt-8 min-w-0 gap-6 sm:mt-10 sm:gap-8">
              <DemostacksToolbar
                sort={sort}
                setSort={setSort}
                selectedAuthors={selectedAuthors}
                setSelectedAuthors={setSelectedAuthors}
                view={view}
                setView={setView}
              />
              <TabsContent value="shared">
                <DemostackCollection demos={visibleDemostacks} view={view} />
              </TabsContent>
              <TabsContent value="personal">
                <EmptyState
                  title="No personal Demostacks yet"
                  description="Demostacks visible only to you will appear here."
                />
              </TabsContent>
              <TabsContent value="archive">
                <EmptyState
                  title="Archive is empty"
                  description="Archived Demostacks will appear here."
                />
              </TabsContent>
            </Tabs>
          </TabsContent>
          <TabsContent value="screenshots">
            <EmptyState
              title="No screenshots yet"
              description="Create a screenshot to see it in this workspace."
              className="mt-10"
            />
          </TabsContent>
        </main>
      </Tabs>
    </TooltipProvider>
  );
}

function PrimaryTab({ value, children }: { value: string; children: ReactNode }) {
  return (
    <TabsTrigger
      value={value}
      className="flex-none rounded-lg px-3 data-active:bg-primary/10 data-active:text-primary data-active:shadow-none!"
    >
      {children}
    </TabsTrigger>
  );
}

type DemostacksToolbarProps = {
  sort: SortMode;
  setSort: (sort: SortMode) => void;
  selectedAuthors: string[];
  setSelectedAuthors: (authors: string[]) => void;
  view: ViewMode;
  setView: (view: ViewMode) => void;
};

function DemostacksToolbar({
  sort,
  setSort,
  selectedAuthors,
  setSelectedAuthors,
  view,
  setView,
}: DemostacksToolbarProps) {
  function toggleAuthor(author: string, checked: boolean) {
    setSelectedAuthors(
      checked ? [...selectedAuthors, author] : selectedAuthors.filter((item) => item !== author),
    );
  }

  return (
    <div className="flex min-w-0 flex-col gap-4 border-b lg:flex-row lg:items-end lg:justify-between">
      <TabsList variant="line">
        <WorkspaceTab value="shared" icon={Users}>
          <span className="sm:hidden">Team</span>
          <span className="hidden sm:inline">Shared with Team</span>
        </WorkspaceTab>
        <WorkspaceTab value="personal" icon={User}>
          Personal
        </WorkspaceTab>
        <WorkspaceTab value="archive" icon={Archive}>
          Archive
        </WorkspaceTab>
      </TabsList>

      <div className="flex w-full flex-wrap items-center gap-2 pb-3 lg:w-auto lg:gap-3 lg:pb-2">
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="outline"
                size="lg"
                className="mr-auto rounded-xl border-0 bg-card text-muted-foreground shadow-border"
              >
                <SortAscending className="size-5" />
                {sortLabels[sort]}
              </Button>
            }
          />
          <DropdownMenuContent align="end" className="w-48">
            <DropdownMenuRadioGroup
              value={sort}
              onValueChange={(value: string) => setSort(value as SortMode)}
            >
              <DropdownMenuLabel>Sort by</DropdownMenuLabel>
              {Object.entries(sortLabels).map(([value, label]) => (
                <DropdownMenuRadioItem key={value} value={value}>
                  {label}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="outline"
                size="lg"
                className={cn(
                  "rounded-xl border-0 bg-card text-muted-foreground shadow-border",
                  selectedAuthors.length && "bg-muted",
                )}
                aria-label="Filter by creator"
              >
                <Funnel className="size-5" />
                <span className="hidden sm:inline">Filter</span>
                {selectedAuthors.length > 0 && (
                  <span className="flex size-5 items-center justify-center rounded-full bg-primary text-xs text-primary-foreground">
                    {selectedAuthors.length}
                  </span>
                )}
              </Button>
            }
          />
          <DropdownMenuContent align="end" className="w-52">
            <DropdownMenuGroup>
              <DropdownMenuLabel>Filter by creator</DropdownMenuLabel>
              {demostackAuthors.map((author) => (
                <DropdownMenuCheckboxItem
                  key={author}
                  checked={selectedAuthors.includes(author)}
                  onCheckedChange={(checked: boolean) => toggleAuthor(author, checked)}
                >
                  {author}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuGroup>
            {selectedAuthors.length > 0 && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => setSelectedAuthors([])}>
                  Clear filters
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="outline"
                size="icon-lg"
                className="rounded-xl border-0 bg-card text-muted-foreground shadow-border"
                aria-label="Folder options"
              >
                <FolderSimplePlus className="size-5" />
              </Button>
            }
          />
          <DropdownMenuContent align="end" className="w-44">
            <DropdownMenuItem>
              <FolderSimplePlus />
              New folder
            </DropdownMenuItem>
            <DropdownMenuItem>
              <FolderSimple />
              Manage folders
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <Button
          variant="outline"
          size="icon-lg"
          className={cn(
            "rounded-xl border-0 bg-card text-muted-foreground shadow-border",
            view === "list" && "bg-muted",
          )}
          aria-label={view === "grid" ? "Use list view" : "Use grid view"}
          onClick={() => setView(view === "grid" ? "list" : "grid")}
        >
          {view === "grid" ? <List className="size-5" /> : <SquaresFour className="size-5" />}
        </Button>
      </div>
    </div>
  );
}

function WorkspaceTab({
  value,
  icon: Icon,
  children,
}: {
  value: string;
  icon: typeof Users;
  children: ReactNode;
}) {
  return (
    <TabsTrigger
      value={value}
      className="px-2 text-sm sm:px-4 sm:text-base data-active:text-primary data-active:after:bg-primary"
    >
      <Icon className="size-4 sm:size-5" />
      {children}
    </TabsTrigger>
  );
}

function DemostackCollection({ demos, view }: { demos: Demostack[]; view: ViewMode }) {
  if (!demos.length) {
    return (
      <EmptyState
        title="No matching Demostacks"
        description="Clear or change the active creator filters."
      />
    );
  }

  return (
    <section
      className={cn(
        view === "grid" ? "grid grid-cols-1 gap-6 sm:grid-cols-2 xl:grid-cols-4" : "space-y-3",
      )}
    >
      {demos.map((demostack) => (
        <article
          key={demostack.id}
          className={cn(
            "group min-w-0 cursor-pointer",
            view === "list" &&
              "flex w-full max-w-full items-center gap-3 overflow-hidden rounded-2xl border p-3 transition hover:bg-muted/40 sm:gap-4",
          )}
        >
          <div
            className={cn(
              "relative aspect-video overflow-hidden rounded-2xl border",
              view === "list" && "w-2/5 max-w-44 shrink-0",
            )}
          >
            <img
              src={demostack.image}
              alt=""
              width={1280}
              height={720}
              className="size-full object-cover motion-safe:transition-transform motion-safe:duration-300 motion-safe:group-hover:scale-105"
            />
          </div>

          <div className={cn("min-w-0 space-y-2", view === "grid" ? "mt-4" : "flex-1")}>
            <div className="flex items-center justify-between gap-3">
              <div className="min-w-0 flex-1">
                <h3 className="truncate font-medium transition-colors group-hover:text-primary">
                  {demostack.title}
                </h3>
              </div>
              <CardMenu title={demostack.title} />
            </div>
            <div className="flex min-w-0 items-center gap-2 text-xs text-muted-foreground">
              <Avatar size="sm" className="shrink-0">
                <AvatarImage src={demostack.avatar} alt={demostack.author} />
                <AvatarFallback>{getInitials(demostack.author)}</AvatarFallback>
              </Avatar>
              <span className="truncate">{demostack.author}</span>
              <span aria-hidden>·</span>
              <time className="shrink-0" dateTime="2026-03-02">
                Mar 02
              </time>
            </div>
          </div>
        </article>
      ))}
    </section>
  );
}

function CardMenu({ title }: { title: string }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            size="icon-xs"
            className="rounded-full text-muted-foreground"
            aria-label={`More options for ${title}`}
          >
            <DotsThreeVertical className="size-4" />
          </Button>
        }
      />
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuItem>
          <ArrowSquareOut />
          Open
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PencilSimple />
          Rename
        </DropdownMenuItem>
        <DropdownMenuItem>
          <Copy />
          Duplicate
        </DropdownMenuItem>
        <DropdownMenuItem>
          <FolderSimple />
          Move to folder
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <Archive />
          Archive
        </DropdownMenuItem>
        <DropdownMenuItem variant="destructive">
          <Trash />
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function EmptyState({
  title,
  description,
  className,
}: {
  title: string;
  description: string;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "flex min-h-64 flex-col items-center justify-center gap-2 rounded-2xl border border-dashed bg-muted/40 px-6 text-center",
        className,
      )}
    >
      <p className="font-medium">{title}</p>
      <p className="text-sm text-muted-foreground">{description}</p>
    </div>
  );
}
